CREATE VIRTUAL TABLE launch_search USING fts5(record_id UNINDEXED,campaign_id UNINDEXED,record_type UNINDEXED,body,tokenize='unicode61',prefix='2 3 4');
INSERT INTO launch_search(record_id,campaign_id,record_type,body) SELECT id,id,'Campaign',name||' '||code||' '||status_summary FROM campaigns;
INSERT INTO launch_search(record_id,campaign_id,record_type,body) SELECT id,campaign_id,'Deliverable',title FROM deliverables;
INSERT INTO launch_search(record_id,campaign_id,record_type,body) SELECT id,campaign_id,'Risk',title FROM risks;
INSERT INTO launch_search(record_id,campaign_id,record_type,body) SELECT id,campaign_id,'Milestone',title FROM milestones;
INSERT INTO launch_search(record_id,campaign_id,record_type,body) SELECT id,campaign_id,'Decision',title FROM decisions;
CREATE TRIGGER launch_search_campaigns_insert AFTER INSERT ON campaigns BEGIN INSERT INTO launch_search(record_id,campaign_id,record_type,body) VALUES(new.id,new.id,'Campaign',new.name||' '||new.code||' '||new.status_summary); END;
CREATE TRIGGER launch_search_campaigns_update AFTER UPDATE ON campaigns BEGIN DELETE FROM launch_search WHERE record_id=old.id AND record_type='Campaign'; INSERT INTO launch_search(record_id,campaign_id,record_type,body) VALUES(new.id,new.id,'Campaign',new.name||' '||new.code||' '||new.status_summary); END;
CREATE TRIGGER launch_search_campaigns_delete AFTER DELETE ON campaigns BEGIN DELETE FROM launch_search WHERE record_id=old.id AND record_type='Campaign'; END;
CREATE TRIGGER launch_search_deliverables_insert AFTER INSERT ON deliverables BEGIN INSERT INTO launch_search(record_id,campaign_id,record_type,body) VALUES(new.id,new.campaign_id,'Deliverable',new.title); END;
CREATE TRIGGER launch_search_deliverables_update AFTER UPDATE ON deliverables BEGIN DELETE FROM launch_search WHERE record_id=old.id AND record_type='Deliverable'; INSERT INTO launch_search(record_id,campaign_id,record_type,body) VALUES(new.id,new.campaign_id,'Deliverable',new.title); END;
CREATE TRIGGER launch_search_deliverables_delete AFTER DELETE ON deliverables BEGIN DELETE FROM launch_search WHERE record_id=old.id AND record_type='Deliverable'; END;
CREATE TRIGGER launch_search_risks_insert AFTER INSERT ON risks BEGIN INSERT INTO launch_search(record_id,campaign_id,record_type,body) VALUES(new.id,new.campaign_id,'Risk',new.title); END;
CREATE TRIGGER launch_search_risks_update AFTER UPDATE ON risks BEGIN DELETE FROM launch_search WHERE record_id=old.id AND record_type='Risk'; INSERT INTO launch_search(record_id,campaign_id,record_type,body) VALUES(new.id,new.campaign_id,'Risk',new.title); END;
CREATE TRIGGER launch_search_risks_delete AFTER DELETE ON risks BEGIN DELETE FROM launch_search WHERE record_id=old.id AND record_type='Risk'; END;
CREATE TRIGGER launch_search_milestones_insert AFTER INSERT ON milestones BEGIN INSERT INTO launch_search(record_id,campaign_id,record_type,body) VALUES(new.id,new.campaign_id,'Milestone',new.title); END;
CREATE TRIGGER launch_search_milestones_update AFTER UPDATE ON milestones BEGIN DELETE FROM launch_search WHERE record_id=old.id AND record_type='Milestone'; INSERT INTO launch_search(record_id,campaign_id,record_type,body) VALUES(new.id,new.campaign_id,'Milestone',new.title); END;
CREATE TRIGGER launch_search_milestones_delete AFTER DELETE ON milestones BEGIN DELETE FROM launch_search WHERE record_id=old.id AND record_type='Milestone'; END;
CREATE TRIGGER launch_search_decisions_insert AFTER INSERT ON decisions BEGIN INSERT INTO launch_search(record_id,campaign_id,record_type,body) VALUES(new.id,new.campaign_id,'Decision',new.title); END;
CREATE TRIGGER launch_search_decisions_update AFTER UPDATE ON decisions BEGIN DELETE FROM launch_search WHERE record_id=old.id AND record_type='Decision'; INSERT INTO launch_search(record_id,campaign_id,record_type,body) VALUES(new.id,new.campaign_id,'Decision',new.title); END;
CREATE TRIGGER launch_search_decisions_delete AFTER DELETE ON decisions BEGIN DELETE FROM launch_search WHERE record_id=old.id AND record_type='Decision'; END;
